+        Encapsulator encapsulator = ProviderUtil.getKEM(algoName).newEncapsulator(pubK);
+        assertThrows(IndexOutOfBoundsException.class, () -> encapsulator.encapsulate(-1, secretSize, "Generic"));
+    }
+
