+        ML_DSA_65(STR_ML_DSA_65, STR_ML_DSA_65_OID, ML_DSA_ALGO_FAMILY_NAME, 32, 4032),
+        ML_DSA_87(STR_ML_DSA_87, STR_ML_DSA_87_OID, ML_DSA_ALGO_FAMILY_NAME, 32, 4896);
