+    String STR_ML_KEM_768_OID = "2.16.840.1.101.3.4.4.2";
+    String STR_ML_KEM_1024_OID = "2.16.840.1.101.3.4.4.3";
+
+    String STR_ML_DSA_44_OID = "2.16.840.1.101.3.4.3.17";
+    String STR_ML_DSA_65_OID = "2.16.840.1.101.3.4.3.18";
